<script>
  import { data,profile,updateData,notify,download } from '../lib/store.js';
  import { TERMS, SECTIONS, courseLabel } from '../lib/catalog.js';
  import { academicSummary, creditSum, dropSection, swapSection, meetingLabel } from '../lib/model.js';
  import { WHAT_IF_PROGRAMS, whatIf, termLabel, planningTerms, OFFICIAL } from '../lib/academics.js';
  import Icon from '../lib/components/Icon.svelte';
  import Modal from '../lib/components/Modal.svelte';
  let {view}=$props();
  let summary=$derived(academicSummary($profile,$data));
  let remaining=$derived(summary.requirements.filter(c=>c.status==='Remaining'));
  let futureTerms=$derived(planningTerms($profile));
  let selectedProgram=$state('data');
  let scenario=$state(null);
  let institution=$state('');let transferCourse=$state('');let transferCredits=$state(3);let equivalent=$state('');let transferError=$state('');
  let term=$state('spring-2027');let oldId=$state('');let newId=$state('');let pending=$state(false);let transactionError=$state('');
  let enrolled=$derived($data.enrolledByTerm[term]??[]);
  let oldCourse=$derived(enrolled.find(s=>s.id===oldId));
  let replacement=$derived(SECTIONS.find(s=>s.id===newId));
  function assigned(code){return $data.academics.plan[code]??$profile.plan.terms.find(t=>futureTerms.includes(t.id)&&t.courses.some(c=>c.code===code))?.id??'spring-2027';}
  function move(code,target){updateData({...$data,academics:{...$data.academics,plan:{...$data.academics.plan,[code]:target}}});}
  function savePlan(){download('sample-graduation-plan.txt',`SAMPLE PLAN — not enrollment\n${$profile.name}\n\n`+futureTerms.map(t=>`${termLabel(t)}\n${remaining.filter(c=>assigned(c.code)===t).map(c=>`${c.code} — ${c.title} (${c.credits} credits)`).join('\n')||'No courses planned'}`).join('\n\n'));}
  function addTransfer(){
    transferError='';
    if(!institution.trim()||!transferCourse.trim()||!Number.isFinite(Number(transferCredits))||Number(transferCredits)<=0||Number(transferCredits)>12){transferError='Enter an institution, course code, and a credit amount greater than 0 and no more than 12.';return;}
    const entry={id:`TRANSFER-${Date.now()}`,institution:institution.trim().slice(0,100),course:transferCourse.trim().slice(0,40),credits:Number(transferCredits),equivalent,status:'Needs advisor review'};
    updateData({...$data,academics:{...$data.academics,transfers:[entry,...$data.academics.transfers].slice(0,20)}});
    institution='';transferCourse='';equivalent='';notify('Transfer question saved. It has not been evaluated or applied to your degree.');
  }
  function confirm(){
    const result=view==='drop'?dropSection($data,oldId,term):swapSection($data,$profile,oldId,newId,term);
    if(!result.ok){transactionError=result.message??'Resolve this enrollment issue.';pending=false;return;}
    updateData(result.state);pending=false;oldId='';newId='';transactionError='';notify(view==='drop'?'Class dropped from the sample schedule.':'Swap confirmed. The replacement is now enrolled.');
  }
</script>

{#if view==='graduation-plan'}
  <div class="notice"><Icon name="info"/><p>Arrange remaining requirements across semesters. Planning does not reserve a seat, check every prerequisite, or enroll you in a class.</p></div>
  <div class="section-heading spaced"><h2>Your remaining coursework</h2><button class="button secondary" onclick={savePlan}><Icon name="download" size={16}/>Download plan</button></div>
  <div class="semester-plan-grid">{#each futureTerms as t}{@const courses=remaining.filter(c=>assigned(c.code)===t)}{@const total=creditSum(courses)}<section class="panel padded"><div class="section-heading"><h3>{termLabel(t)}</h3><span class="badge" class:warning={total>18} class:neutral={total<=18}>{total} credits</span></div>{#if total>18}<p class="warning-text">Above the 18-credit planning guide. Review this load with an advisor.</p>{/if}{#each courses as c}<div class="planning-course"><strong>{c.code}</strong><p class="muted small">{c.title} · {c.credits} credits</p><label><span class="sr-only">Move {c.code} to term</span><select value={t} onchange={e=>move(c.code,e.currentTarget.value)}>{#each futureTerms as option}<option value={option}>{termLabel(option)}</option>{/each}</select></label><a class="text-link" href={`#/classes?q=${c.code}`}>Find sections <Icon name="arrow" size={14}/></a></div>{:else}<p class="muted small">No remaining courses assigned.</p>{/each}</section>{/each}</div><p class="fine-print">Only remaining courses appear here; current courses are still in progress. Future terms are planning slots, not a promise of course availability.</p>
{:else if view==='what-if'}
  <section class="panel padded academic-copy"><h2>Explore another path</h2><p>Compare a small illustrative requirement set against completed coursework. This does not change your current major, certificate, transcript, or graduation application.</p><div class="academic-controls"><label>Program scenario<select bind:value={selectedProgram}>{#each WHAT_IF_PROGRAMS as p}<option value={p.id}>{p.name}</option>{/each}</select></label><button class="button primary" onclick={()=>{const program=WHAT_IF_PROGRAMS.find(p=>p.id===selectedProgram);scenario={program,...whatIf($profile,program)};}}>Run report <Icon name="arrow" size={16}/></button></div></section>
  {#if scenario}<section class="panel padded spaced" aria-live="polite"><div class="section-heading"><h2>{scenario.program.name}</h2><span class="badge neutral">Illustrative scenario</span></div><div class="progress-track big"><span style:width={`${scenario.percent}%`}></span></div><p class="muted spaced">{scenario.matches.length} of {scenario.program.codes.length} sample requirements match completed coursework.</p><div class="scenario-columns"><div><h3>Matching coursework</h3><ul class="academic-list">{#each scenario.matches as code}<li>{courseLabel(code)}</li>{:else}<li>No matching courses yet.</li>{/each}</ul></div><div><h3>Still needed in this scenario</h3><ul class="academic-list">{#each scenario.missing as code}<li>{courseLabel(code)}</li>{:else}<li>All listed sample requirements match.</li>{/each}</ul></div></div><p class="fine-print">This is a limited sample comparison, not a UC program curriculum or official equivalency decision. An advisor must evaluate the complete program and any additional rules.</p><a class="button secondary spaced" href="#/academics/bearcat-network">Discuss this scenario with advising <Icon name="arrow" size={16}/></a></section>{/if}
{:else if view==='transfer-credit'}
  <div class="academic-resource-layout"><section class="panel padded academic-copy"><h2>Prepare a transfer-credit question</h2><p>Record coursework you want an advisor to review. A proposed course match does not establish an approved equivalency or add earned credit.</p><form class="academic-form" onsubmit={e=>{e.preventDefault();addTransfer();}}><label>Previous institution<input maxlength="100" bind:value={institution}/></label><div class="form-two-columns"><label>External course code<input maxlength="40" bind:value={transferCourse}/></label><label>Credits<input type="number" min="0.5" max="12" step="0.5" bind:value={transferCredits}/></label></div><label>Possible UC course to discuss<select bind:value={equivalent}><option value="">Not sure / general credit</option>{#each summary.requirements as c}<option value={c.code}>{c.code} — {c.title}</option>{/each}</select></label>{#if transferError}<p class="warning-text" role="alert">{transferError}</p>{/if}<button type="submit" class="button primary">Save for advisor review <Icon name="plus" size={16}/></button></form></section><aside class="panel padded academic-copy"><h3>Credit and equivalency are different</h3><p>Accepted credits may contribute to a credit total without meeting a specific degree requirement. All saved questions below remain pending review.</p><a class="button secondary" href={OFFICIAL.transfer} target="_blank" rel="noreferrer">Official credit evaluation guidance <Icon name="external" size={15}/></a><a class="academic-related" href="#/academics/bearcat-network">Discuss with your advisor <Icon name="arrow" size={15}/></a></aside></div>
  <section class="panel padded spaced"><h2>Saved transfer questions</h2>{#each $data.academics.transfers as t}<div class="detail-section"><div><strong>{t.course} · {t.institution}</strong><p class="muted small">{t.credits} credits · Proposed match: {t.equivalent||'General credit / not sure'}</p><span class="badge warning">Needs advisor review</span></div><button class="button quiet" aria-label={`Remove transfer question ${t.course}`} onclick={()=>updateData({...$data,academics:{...$data.academics,transfers:$data.academics.transfers.filter(x=>x.id!==t.id)}})}>Remove</button></div>{:else}<p class="muted spaced">No transfer-credit questions saved.</p>{/each}</section>
{:else if view==='bearcat-network'}
  <div class="academic-resource-layout"><section class="panel padded academic-copy"><h2>Your advising network</h2><p>Connect with academic and specialized advisors to discuss requirements, registration, transfer questions, and graduation plans.</p><a class="button primary" href={OFFICIAL.network} target="_blank" rel="noreferrer">Open My Bearcat Network <Icon name="external" size={16}/></a><a class="text-link spaced" href={OFFICIAL.advising} target="_blank" rel="noreferrer">How to schedule an appointment <Icon name="external" size={15}/></a><div class="scenario-columns spaced"><div><h3>Academic advisors</h3><p>Degree requirements, course sequencing, and graduation planning.</p></div><div><h3>Other student advisors</h3><p>Co-op planning and specialized academic support.</p></div></div></section><aside class="panel padded academic-copy"><h3>Bring to your appointment</h3><ul class="academic-list"><li>Your degree audit and remaining requirements</li><li>A draft semester plan or what-if comparison</li><li>Transfer-credit questions and original course materials</li><li>Any registration or graduation questions</li></ul><a class="academic-related" href="#/academics/graduation-plan">Review your graduation plan <Icon name="arrow" size={15}/></a></aside></div>
{:else if view==='term-information'}
  <div class="academic-controls"><label>Term<select bind:value={term}>{#each TERMS as t}<option value={t.id}>{t.label}</option>{/each}</select></label></div><div class="metrics-grid three"><div class="panel metric"><span>Enrolled credits</span><strong>{creditSum(enrolled)}</strong><p>{termLabel(term)}</p></div><div class="panel metric"><span>Confirmed classes</span><strong>{enrolled.length}</strong><p>Cart items are excluded</p></div><div class="panel metric"><span>Registration access</span><strong class="smaller">{TERMS.find(t=>t.id===term)?.registrationOpen?'Open':'Closed'}</strong><p>{TERMS.find(t=>t.id===term)?.reason}</p></div></div><section class="panel padded academic-copy"><h2>Term resources</h2><a class="academic-related" href={`#/classes?tab=schedule&term=${term}`}>My Class Schedule <Icon name="arrow" size={16}/></a><a class="academic-related" href="#/academics/grades">View My Grades <Icon name="arrow" size={16}/></a><a class="academic-related" href="#/academics/deadlines">Dates and Deadlines <Icon name="arrow" size={16}/></a></section>
{:else if view==='drop'||view==='swap'}
  <section class="panel padded academic-copy"><h2>{view==='drop'?'Choose a class to drop':'Replace an enrolled section'}</h2><p>{view==='drop'?'Review the class and credit change before confirming.':'The replacement must pass all registration checks. If it cannot be added, your existing class remains enrolled.'}</p><div class="academic-form"><label>Enrollment term<select bind:value={term} onchange={()=>{oldId='';newId='';transactionError='';}}>{#each TERMS as t}<option value={t.id}>{t.label}</option>{/each}</select></label><label>Currently enrolled class<select bind:value={oldId}><option value="">Select a class</option>{#each enrolled as c}<option value={c.id}>{c.code} · Section {c.section} · {c.title}</option>{/each}</select></label>{#if view==='swap'}<label>Replacement section<select bind:value={newId}><option value="">Select a replacement</option>{#each SECTIONS.filter(s=>s.termId===term&&s.id!==oldId) as c}<option value={c.id}>{c.code} · {c.section} · {meetingLabel(c)} · {c.seats} seats</option>{/each}</select></label>{/if}
    {#if !TERMS.find(t=>t.id===term)?.registrationOpen}<p class="warning-text">Changes are closed for this term. Choose an open term to continue.</p>{:else if !enrolled.length}<p class="muted">No classes are enrolled for this term. <a class="text-link" href="#/classes?term=spring-2027">Find classes <Icon name="arrow" size={15}/></a></p>{/if}{#if transactionError}<p class="warning-text" role="alert">{transactionError}</p>{/if}<button class="button primary" disabled={!oldCourse||!TERMS.find(t=>t.id===term)?.registrationOpen||(view==='swap'&&!replacement)} onclick={()=>{transactionError='';pending=true;}}>Review {view==='drop'?'drop':'swap'} <Icon name="arrow" size={16}/></button></div><a class="text-link spaced" href={`#/classes?tab=schedule&term=${term}`}>View confirmed schedule <Icon name="arrow" size={15}/></a></section>
{/if}
{#if pending&&oldCourse}<Modal title={view==='drop'?'Confirm class drop':'Review class swap'} onclose={()=>pending=false}><div class="academic-copy"><p><strong>{view==='drop'?'Remove':'Replace'} {oldCourse.code} · section {oldCourse.section}</strong></p><p>{oldCourse.title} · {oldCourse.credits} credits</p>{#if view==='swap'&&replacement}<p><strong>With {replacement.code} · section {replacement.section}</strong></p><p>{replacement.title} · {meetingLabel(replacement)}</p>{/if}<p class="muted">{view==='drop'?`Your sample term total becomes ${creditSum(enrolled)-oldCourse.credits} credits.`:'The complete replacement is checked before either enrollment changes.'}</p><p class="fine-print">Sample enrollment only. Check real deadlines and academic implications with UC.</p></div><div class="modal-actions"><button class="button secondary" onclick={()=>pending=false}>Keep current class</button><button class="button" class:danger-button={view==='drop'} class:primary={view==='swap'} onclick={confirm}>Confirm {view==='drop'?'drop':'swap'}</button></div></Modal>{/if}
